def kernel_lu_base(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # Outer loop over rows.
    for i in seq(0, n):

        # Compute the strict lower-triangular part (L) of row i.
        # This matches the standard PolyBench LU algorithm:
        #   A[i, j] = (A[i, j] - sum_{k=0}^{j-1} A[i, k] * A[k, j]) / A[j, j]
        for j in seq(0, i):
            # Keep A[i, j] in a scalar accumulator while forming the dot product
            # to improve register reuse and reduce memory traffic.
            acc: DATA_TYPE
            acc = A[i, j]
            for k in seq(0, j):
                acc += -A[i, k] * A[k, j]
            A[i, j] = acc / A[j, j]

        # Compute the diagonal and upper-triangular part (U) of row i.
        # We express it as a sequence of rank-1 updates:
        #   for each k < i, update the entire row segment A[i, i:n].
        #
        # Mathematically:
        #   A[i, j] <- A[i, j] - sum_{k=0}^{i-1} A[i, k] * A[k, j],  j >= i
        #
