aik_exprs = u_k_loop.find("A[i, k]", many=True) # all A[i, k] uses in that loop
kernel_lu = bind_expr(kernel_lu, aik_exprs, "aik")

# 2. Run algebraic simplifications and dead-code cleanups.
kernel_lu = simplify(kernel_lu)

# 3. Ensure the externally visible C symbol remains 'kernel_lu'.
